<?php
require_once dirname(__DIR__) . '/app/bootstrap.php';require_once dirname(__DIR__) . '/app/layout.php';require_permission('import');$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(empty($_FILES['csv']['tmp_name'])||$_FILES['csv']['error']!==UPLOAD_ERR_OK)$errors[]='Choose a valid CSV file.';else{$h=fopen($_FILES['csv']['tmp_name'],'rb');$head=fgetcsv($h);$normalize=fn($v)=>preg_replace('/[^a-z0-9]+/','',strtolower((string)$v));$aliases=['productgroup'=>'group','sku'=>'sku','productname'=>'product_name','productcode'=>'product_code','unitcost'=>'unit_cost','labourcost'=>'labour_cost','targetmargin'=>'target_margin','targetmarginpercent'=>'target_margin','msrp'=>'msrp','avgcompetitorprice'=>'competitor_price','retailpriceexclvat'=>'retail_price','targettradediscount'=>'trade_discount','targettradediscountpercent'=>'trade_discount','actualtradeprice'=>'trade_price','minmargin'=>'minimum_margin','minmarginpercent'=>'minimum_margin','wholesale'=>'is_wholesale'];$map=[];foreach($head?:[] as $i=>$name){$key=$normalize($name);if(isset($aliases[$key]))$map[$i]=$aliases[$key];}if(!in_array('product_name',$map,true))$errors[]='The CSV must include a Product Name column.';else{$count=0;$groupStmt=db()->prepare('INSERT INTO product_groups(name) VALUES(?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)');while(($row=fgetcsv($h))!==false){$raw=[];foreach($map as $i=>$key)$raw[$key]=$row[$i]??'';if(empty(trim((string)($raw['product_name']??''))))continue;if(!empty($raw['group'])){$groupStmt->execute([trim($raw['group'])]);$raw['group_id']=(int)db()->lastInsertId();}foreach(['target_margin','trade_discount','minimum_margin'] as $key)if(isset($raw[$key])&&is_numeric($raw[$key])&&(float)$raw[$key]>=1)$raw[$key]=(float)$raw[$key]/100;save_product(clean_product($raw));$count++;}fclose($h);flash('success',"$count products imported.");redirect('products.php');}}}
page_header('Import');?><div class="page-title"><h1>CSV import</h1></div><?php foreach($errors as $e1):?><div class="alert error"><?=e($e1)?></div><?php endforeach?><section class="card narrow"><p>Upload a CSV exported from the workbook. Column names are matched automatically; calculated columns are ignored and recalculated by the application.</p><form method="post" enctype="multipart/form-data"><?=csrf_field()?><label>CSV file<input type="file" name="csv" accept=".csv,text/csv" required></label><button class="button primary">Import products</button></form></section><?php page_footer();?>
